WHERE 

    AND a.management_item_code = #{criteria.managementItemCode}


    AND a.evaluation_year = #{criteria.evaluationYear}


    AND a.achievement_status = #{criteria.achievementStatus}


    AND u.login_id ILIKE CONCAT('%', #{criteria.teacherName}, '%')


    AND (1 = 0

            OR a.teacher_user_id = #{requesterUserId}


            OR EXISTS (
                SELECT 1
                FROM organization_user_mappings r
                JOIN organization_user_mappings t ON t.organization_code = r.organization_code
                WHERE r.user_id = #{requesterUserId}
                  AND r.status = 'ACTIVE'
                  AND t.user_id = a.teacher_user_id
                  AND t.status = 'ACTIVE'
            )


            OR EXISTS (
                SELECT 1
                FROM evaluation_organization_mappings p
                JOIN organization_user_mappings t ON t.organization_code = p.organization_code
                WHERE p.user_id = #{requesterUserId}
                  AND p.business_type = 'FACULTY_ACHIEVEMENT'
                  AND p.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL')
                  AND t.user_id = a.teacher_user_id
                  AND t.status = 'ACTIVE'
            )

    )

mapper.select:
SELECT 


ORDER BY a.achievement_date DESC, a.achievement_id DESC
LIMIT #{criteria.pageSize}
OFFSET #{criteria.pageOffset}

SELECT finalization_id
FROM evaluation_finalizations
WHERE target_user_id = #{teacherId}
  AND evaluation_year = #{year}
FOR UPDATE

SELECT COUNT(*)
FROM education_achievements
WHERE teacher_user_id = #{write.teacherUserId}
  AND evaluation_year = #{write.evaluationYear}
  AND achievement_type = 'EMPLOYMENT_RATE_IMPROVEMENT'
  AND management_item_code = TRIM(#{write.request.managementItemCode})
  AND achievement_date = #{write.request.achievementDate}
  AND deleted_yn = 'N'

  AND achievement_id != #{write.achievementId}

